#include <iostream>
#include <iomanip>

int main()
{
  std::string s = "";

  errno = 0;
  char* end2 = NULL;
  std::string core = s.substr(0, s.size() - 1);
  double v = std::strtod(core.c_str(), &end2);

  std::cout << errno << std::endl;
  std::cout << std::fixed << std::setprecision(1) << std::endl;
  std::cout << v << std::endl;
}
